TLM.f("Sancti/05-20",{"officium":"S. Bernardini Senensis Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Dómine Jesu, qui beáto Bernardíno Confessóri tuo exímium sancti nóminis tui amórem tribuísti: ejus, quǽsumus, méritis et intercessióne, spíritum nobis tuæ dilectiónis benígnus infúnde:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja."},{"k":"ref","la":"Jas 1:1-2"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:27-29"},{"k":"text","la":"In illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Laudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum: quibus nos et præséntibus éxui malis confídimus et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8f6d07275042f4c9":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. <i>Aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 36, 30, 31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne će posrnuti. (Aleluja, Aleluja.) (Ps. 36, 1). Ne zaviđaj sreći ^rješnika i zlotvora! Slava Ocu. Pravednikova.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"9b618b11cd39242b":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse, koji si blaženom Bernardinu priznavaocu svome udijelio izvanrednu ljubav svetoga svog imena, ulij nam, molimo, po njegovim zaslugama i zagovoru duh svoje ljubavi:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine Isuse, koji si bi. Bernardinu, priznavaocu svomu, udijelio divnu ljubav svoga svetog imena, ulij nam, molimo, njegovim zaslugama i zagovorom, duh ljubavi svoje, koji zivis i kraljuješ ...","knRef":"Kniewald 1942, str. 578–579 (snimka 290) (OCR)"},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 31, 8-11). Blago čovjeku, koji se našao bez ljage i koji ne ide za zlatom niti se uzda u novac i blago. Tko je taj, da ga hvalimo? Jer je u svom životu učinio divna djela. Vječno će biti slavan, koji je u tom prokušan i savršen; mogao je sagriješiti, a nije sagriješio, i učiniti zlo, a nije učinio. Zato su njegova dobra priznata od Gospodina, i njegove će milostinje kazivati čitav zbor svetih. t!82","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"cd5ee57da85dcf6e":{"t":"Jak 1, 12, Eccli 45, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života, <i>aleluja</i>.\nGospodin ga je ljubio i ukrasio, zaodjenuo ga je haljinom slave. <i>Aleluja</i>.","kn":"Aleluja, aleluja (Jk. 1, 12). Blago čovjeku, koji pretrpi napast, jer će primiti vijenac slave, kad bude prokušan, Aleluja (Crkv. 45, 9). Ljubio ga je Gospodin i ukrasio ga, odjenuo ga haljinom slave, Aleluja.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"9c583f5745d0c082":{"t":"Mt 19, 27-29\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Što će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem kad u vrijeme preporoda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi koji ste pošli za mnom sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu ili polja, primit će stoput više i imat će vječni život.","kn":"t Slijedi sveto evanđelje po Mateju (19, 27-29). U ono vrijeme reće Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Sto će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem, da kad u vrijeme preiraroda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi, koji ste pošli Za mnom, sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću ili braću Hi sestre ili oca ili majku ili ženu ili djecu ili polja, primit će stoput više i imat će vječni život.","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"668d2b3f25be2f1c":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć. <i>Aleluja</i>.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"18a58d3552d982fb":{"t":"Posvećujemo ti, Gospodine, žrtve hvale na spomen tvojih svetih i uzdamo se da ćeš nas po njima izbaviti od sadašnjih i od budućih zala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, žrtve hvale spominjući se Tvojih svetih i uzdajućl se, da će nas oni osloboditi i sadašnjih i budućih zala, po G. n.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka: Korizmeno predslovlje.","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"9b17da23cc266813":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim. <i>Aleluja</i>.","kn":"(Mt. 24, 46-47). Blago onomu slugi, koga nađe njegov gospodar budna, kad dođe! zaista vam kažem, da će ga postaviti nad svim imanjem svojim.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni :nebeskom hranom i pićem, ponizno Te molimo; Bože naš, da nas zaštite molitve onoga, kojega se spominjemo primajući Tvoje darove. Po G. n.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"}}});
